def switch_letters(input_string):
    output_string = ""
    for char in input_string:
        if char.isalpha():
            if char.islower():
                new_char = chr((ord(char) - ord('a') + 1) % 26 + ord('a'))
            else:
                new_char = chr((ord(char) - ord('A') + 1) % 26 + ord('A'))
            output_string += new_char
        else:
            output_string += "_"
    return output_string

